+export function assertManagedFile(file: string, directory = false): boolean {
+  try {
+    const stat = lstatSync(file);
+    if (directory ? stat.isDirectory() : stat.isFile() && stat.nlink === 1) return true;
+    return reject("검토 관리 경로가 일반 파일·디렉터리가 아니다");
+  } catch (error) {
