+export const REVIEW_PRE_USAGE = "pace agent review-pre --target <TASK.md> --author-provider <제공자>";
+const PRE = "PRE-REVIEW.json";
+
+type Attempt = {
+  hash: string;
+  provider: string;
+  cross: boolean;
+  status: "pass" | "fail" | "unavailable";
